UPDATE cases
SET summary = (SELECT summary FROM corrections WHERE rid=cases.rowid),
    facts = (SELECT summary FROM corrections WHERE rid=cases.rowid) || ' recordrecordrecord、timerecordversion，record。',
    reasoning = CASE (rowid % 5)
      WHEN 0 THEN 'researchrecord、timerecordsourcerecord；recordplatformrecordrecord。'
      WHEN 1 THEN 'record，recordrecordrecordtime、recordfieldrecord。'
      WHEN 2 THEN 'recordrecordrecord，recorddatarecord。'
      WHEN 3 THEN 'recordresearchrecord；record、recordrecordrecord。'
      ELSE 'record、recordrecordrecordprivacy minimization，recordauthenticityrecord。'
    END,
    holding = CASE (rowid % 4)
      WHEN 0 THEN 'record：recordmaterialsrecord，recordrecord。'
      WHEN 1 THEN 'record：record；record。'
      WHEN 2 THEN 'record：recordmaterialsrecordsource、recordtimerecordversionrecord，record。'
      ELSE 'record：recordmaterials，record，record。'
    END,
    ruling = 'recordrecord，record。'
WHERE rowid BETWEEN 4 AND 93;

